    _ensure_workspace_skill("awmf", {
        "SKILL.md": _AWMF_SKILL_MD,
        "manifest.json": _AWMF_MANIFEST,
        "bin/awmf.py": _AWMF_PY,
    })
    # F7b: a2a-agent se RENOMBRÓ a tnode-a2a (2.0.0, dos roles). El dir viejo
